// Verifica se la cartella padre è stata trovata
const items = $input.all();

if (!items || items.length === 0) {
  const folderName = $('Workflow Configuration').first().json.parentFolderName;
  throw new Error('Cartella padre "' + folderName + '" non trovata nel Drive. Assicurati che esista nella root del Drive.');
}

// La risposta di Google Drive può essere in items[0].json o items[0].json.files[]
let parentFolder;
if (items[0].json.files && Array.isArray(items[0].json.files)) {
  // Risposta con struttura files[]
  if (items[0].json.files.length === 0) {
    const folderName = $('Workflow Configuration').first().json.parentFolderName;
    throw new Error('Cartella padre "' + folderName + '" non trovata nel Drive.');
  }
  parentFolder = items[0].json.files[0];
} else {
  // Risposta diretta
  parentFolder = items[0].json;
}

if (!parentFolder || !parentFolder.id) {
  throw new Error('ID cartella padre non trovato nella risposta');
}

return {
  json: {
    parentFolderId: parentFolder.id,
    parentFolderName: parentFolder.name || $('Workflow Configuration').first().json.parentFolderName
  }
};

// Combina i dati di Perplexity con i dati del vino per mantenerli nel flusso
const perplexityData = $input.item.json;
const vinoData = $('Prepare Perplexity Request').item.json;

// Combina i dati mantenendo la struttura di Perplexity e aggiungendo i dati del vino
return {
  json: {
    ...perplexityData,
    cantina_research: vinoData.cantina_research || null,
    vino: {
      domain: vinoData.cantina || vinoData.domain,
      nome_vino: vinoData.nome_vino,
      anno: vinoData.annata || vinoData.anno,
      litraggio: vinoData.categoria || vinoData.litraggio,
      outputFolderId: vinoData.outputFolderId,
      productFolderId: vinoData.productFolderId
    }
  }
};

// Validazione e parsing dei dati
// Supporta sia { data: [...] } che array diretto
let vini = [];
if (Array.isArray($json)) {
  vini = $json;
} else if ($json && Array.isArray($json.data)) {
  vini = $json.data;
} else if ($json && $json.data && typeof $json.data === 'string') {
  // Se data è una stringa, prova a parsarla
  try {
    const parsed = JSON.parse($json.data);
    vini = Array.isArray(parsed) ? parsed : [parsed];
  } catch (e) {
    throw new Error('Dati JSON non validi: impossibile parsare il campo data');
  }
} else {
  throw new Error('Dati JSON non validi: formato non riconosciuto. Atteso array o oggetto con campo "data"');
}

if (vini.length === 0) {
  throw new Error('Nessun vino trovato nel file JSON');
}

// Recupera l'ID della cartella di output (root) dal nodo Store Folder ID
const storeFolderNode = $('Store Folder ID');
if (!storeFolderNode || !storeFolderNode.item || !storeFolderNode.item.json || !storeFolderNode.item.json.outputFolderId) {
  throw new Error('ID cartella di output non trovato. Assicurati che la cartella sia stata creata correttamente.');
}
const rootFolderId = storeFolderNode.item.json.outputFolderId;

// Recupera l'ID della sottocartella PRODOTTO
const storeProductFolderNode = $('Store Product Folder ID');
if (!storeProductFolderNode || !storeProductFolderNode.item || !storeProductFolderNode.item.json || !storeProductFolderNode.item.json.productFolderId) {
  throw new Error('ID cartella prodotto non trovato. Assicurati che la sottocartella PRODOTTO sia stata creata correttamente.');
}
const productFolderId = storeProductFolderNode.item.json.productFolderId;

// Validazione campi obbligatori per ogni vino
const viniValidi = vini.filter((vino, index) => {
  if (!vino.domain || !vino.nome_vino) {
    console.warn(`Vino all'indice ${index} ignorato: campi obbligatori mancanti`);
    return false;
  }
  return true;
});

if (viniValidi.length === 0) {
  throw new Error('Nessun vino valido trovato dopo la validazione');
}

// Restituisci ogni vino come item separato con gli ID cartella
return viniValidi.map(vino => ({
  json: {
    ...vino,
    outputFolderId: rootFolderId,
    productFolderId: productFolderId
  }
}));

// Filtra i vini escludendo quelli che hanno già il file di descrizione esistente
// I dati arrivano dal Merge: items da Estrae primo prodotto e item da Get Existing Files
// FIX: Confronto basato su domain + nome_vino (chiave primaria), ignorando varianti annata/litraggio
const allItems = $input.all();

// Separa i vini dai file esistenti
let allVini = [];
let existingFilesResponse = null;

for (const item of allItems) {
  if (item.json.files && Array.isArray(item.json.files)) {
    existingFilesResponse = item.json;
  } else if (item.json.domain || item.json.nome_vino) {
    allVini.push(item);
  }
}

if (allVini.length === 0) {
  throw new Error('Nessun vino trovato nel merge');
}

// Estrae i nomi dei file esistenti dalla risposta di Google Drive
let existingFileNames = [];
let existingFilesArray = [];
if (existingFilesResponse && existingFilesResponse.files && Array.isArray(existingFilesResponse.files)) {
  existingFilesArray = existingFilesResponse.files;
  existingFileNames = existingFilesArray.map(file => (file.name || '').toLowerCase().trim()).filter(name => name);
}

console.log('File esistenti trovati: ' + existingFileNames.length);
console.log('File esistenti: ' + existingFileNames.join(', '));

// Estrae la chiave base (domain_nomevino) da un nome file esistente
// Rimuove estensione, annata (pattern _YYYY) e litraggio (pattern _XXXml o _X.Xl)
function extractBaseKey(fileName) {
  let name = fileName.replace(/\.md$/i, '').toLowerCase().trim();
  // Rimuove pattern annata: _2020, _2021, _2022, _2023, _2024, _2025, _2026 ecc
  name = name.replace(/_20\d{2}/g, '');
  // Rimuove pattern litraggio: _750ml, _1.5l, _375ml, _magnum ecc
  name = name.replace(/_\d+(\.\d+)?(ml|l|cl)$/i, '');
  name = name.replace(/_magnum$/i, '');
  name = name.replace(/_jeroboam$/i, '');
  name = name.replace(/_mathusalem$/i, '');
  // Rimuove trailing underscore multipli
  name = name.replace(/_+$/, '').replace(/_+/g, '_');
  return name;
}

// Genera la chiave base per un vino dal JSON (solo domain + nome_vino)
function getBaseKey(vino) {
  const domain = (vino.domain || '').trim().toLowerCase();
  const nomeVino = (vino.nome_vino || '').trim().toLowerCase();
  if (!domain || !nomeVino) return null;
  return (domain + '_' + nomeVino).replace(/\s+/g, '_').replace(/_+/g, '_');
}

// Costruisce un set di chiavi base dai file esistenti per lookup O(1)
const existingBaseKeys = new Set();
for (const fileName of existingFileNames) {
  const baseKey = extractBaseKey(fileName);
  if (baseKey) {
    existingBaseKeys.add(baseKey);
    console.log('Chiave base estratta: ' + baseKey + ' (da ' + fileName + ')');
  }
}

// Filtra i vini che non hanno ancora il file (basandosi sulla chiave base)
const viniDaProcessare = allVini.filter(item => {
  const vino = item.json;
  const baseKey = getBaseKey(vino);

  if (!baseKey) {
    console.log('Vino senza chiave valida, incluso per gestione errori');
    return true;
  }

  // Verifica se esiste già un file con la stessa chiave base
  const fileExists = existingBaseKeys.has(baseKey);

  if (fileExists) {
    const vinoInfo = vino.domain + ' ' + vino.nome_vino + ' ' + (vino.anno || '') + ' ' + (vino.litraggio || '');
    console.log('Prodotto già esistente (chiave: ' + baseKey + '): ' + vinoInfo + ' - SKIP');
  } else {
    console.log('Nuovo prodotto (chiave: ' + baseKey + '): ' + vino.domain + ' ' + vino.nome_vino);
  }

  return !fileExists;
});

// FIX: Se non ci sono vini da processare, restituisci un item con flag isEmpty
// In questo modo il flusso continua e Check Empty Array può decidere correttamente
if (viniDaProcessare.length === 0) {
  console.log('Tutti i vini hanno già le descrizioni generate. Nessun file da processare.');
  // Passa i file esistenti per il resoconto finale
  return [{ json: { 
    isEmpty: true, 
    existingFiles: existingFilesArray.map(f => f.name).filter(Boolean),
    existingFilesCount: existingFilesArray.length
  } }];
}

console.log(viniDaProcessare.length + ' vini da processare su ' + allVini.length + ' totali');

return viniDaProcessare;

// Gestisce il caso in cui tutti i vini hanno già i file generati
// I file esistenti sono passati direttamente da Filter Existing Files
const outputFolderName = $('Workflow Configuration').first().json.outputFolderName || 'cartella di output';

// Recupera i file esistenti dall'input (passati da Filter Existing Files)
let existingFiles = [];
const inputData = $json || {};

// Prima prova a usare i dati passati direttamente
if (inputData.existingFiles && Array.isArray(inputData.existingFiles)) {
  existingFiles = inputData.existingFiles;
} else {
  // Fallback: recupera da Get Existing Files
  try {
    const getExistingFilesNode = $('Get Existing Files');
    if (getExistingFilesNode && getExistingFilesNode.first()) {
      const response = getExistingFilesNode.first().json;
      if (response && response.files && Array.isArray(response.files)) {
        existingFiles = response.files.map(f => f.name).filter(Boolean);
      }
    }
  } catch (e) {
    console.log('Impossibile recuperare file esistenti: ' + e.message);
  }
}

const existingFilesCount = existingFiles.length;
const existingFileNames = existingFiles.join('\n- ');

return {
  json: {
    totalFiles: 0,
    fileNames: '',
    existingFilesCount: existingFilesCount,
    existingFileNames: existingFileNames,
    outputFolderName: outputFolderName
  }
};

// Raccoglie tutti i vini processati e prepara il messaggio finale
// Questo nodo viene eseguito quando Split In Batches completa tutti i batch (output 'done')
try {
  const filterNode = $('Filter Existing Files');
  let allVini = [];

  if (filterNode && filterNode.all && filterNode.all().length > 0) {
    allVini = filterNode.all().map(item => item.json);
  } else {
    const inputItems = $input.all();
    if (inputItems && inputItems.length > 0) {
      allVini = inputItems.map(item => item.json);
    }
  }

  const totalFiles = allVini.length;

  if (totalFiles === 0) {
    throw new Error('Nessun vino processato');
  }

  const fileNames = allVini.map(vino => {
    if (!vino.domain || !vino.nome_vino) return 'File sconosciuto';
    const anno = vino.anno ? '_' + vino.anno : '';
    const litri = vino.litraggio ? '_' + vino.litraggio : '';
    return vino.domain + '_' + vino.nome_vino + anno + litri + '.md';
  }).join('\n- ');

  const outputFolderName = $('Workflow Configuration').first().json.outputFolderName || 'cartella di output';

  // Recupera anche i file esistenti per il resoconto completo
  let existingFiles = [];
  try {
    const getExistingFilesNode = $('Get Existing Files');
    if (getExistingFilesNode && getExistingFilesNode.first()) {
      const response = getExistingFilesNode.first().json;
      if (response && response.files && Array.isArray(response.files)) {
        existingFiles = response.files.map(f => f.name).filter(Boolean);
      }
    }
  } catch (e) {}

  return {
    json: {
      totalFiles: totalFiles,
      fileNames: fileNames,
      existingFilesCount: existingFiles.length,
      existingFileNames: existingFiles.join('\n- '),
      outputFolderName: outputFolderName
    }
  };
} catch (error) {
  const outputFolderName = $('Workflow Configuration').first().json.outputFolderName || 'cartella di output';
  return {
    json: {
      totalFiles: 0,
      fileNames: '',
      existingFilesCount: 0,
      existingFileNames: '',
      outputFolderName: outputFolderName
    }
  };
}

// 1. Estrae il testo generato dal modello
let rawHTML = null;
const output = ($input.item.json || {}).output;

if (typeof output === 'string') {
  rawHTML = output;
} else if (output && Array.isArray(output) && output[0] && output[0].content && Array.isArray(output[0].content) && output[0].content[0]) {
  rawHTML = output[0].content[0].text;
} else if (output && output.text) {
  rawHTML = output.text;
} else {
  throw new Error('Risposta del modello non valida: struttura dati inattesa. Output ricevuto: ' + JSON.stringify(output).substring(0, 200));
}

if (!rawHTML || typeof rawHTML !== 'string') {
  throw new Error('Contenuto HTML non valido o vuoto');
}

// 2. Pulizia: Rimuove i tag strutturali pesanti mantenendo intatta la formattazione interna (em, strong, span)
let cleanHTML = rawHTML
  .replace(/<!DOCTYPE html>|<\/?html.*?>|<\/?head>|<\/?body>|<meta.*?>|<title>.*?<\/title>/gi, '')
  .trim();

// 3. Recupera i dati del vino: currentItem.vino + fallback su Split In Batches (più stabile nei loop)
const currentItem = $input.item.json || {};
const batchNode = $('Split In Batches');
const batchItem = (batchNode && batchNode.item && batchNode.item.json) ? batchNode.item.json : {};

let vino = currentItem.vino || {};

vino = {
  domain: vino.domain || batchItem.domain || currentItem.domain || null,
  nome_vino: vino.nome_vino || batchItem.nome_vino || currentItem.nome_vino || null,
  anno: vino.anno || batchItem.anno || currentItem.anno || null,
  litraggio: vino.litraggio || batchItem.litraggio || currentItem.litraggio || null,
  outputFolderId: vino.outputFolderId || batchItem.outputFolderId || currentItem.outputFolderId || null,
  productFolderId: vino.productFolderId || batchItem.productFolderId || currentItem.productFolderId || null
};

// Fallback: estrai domain/nome_vino/anno dall'<h2>
if (!vino.nome_vino || !vino.domain || !vino.anno) {
  const m = rawHTML.match(/<h2>\s*([^<]+?)\s*-\s*([^<]+?)(?:\s+(\d{4}))?\s*<\/h2>/i);
  if (m) {
    vino.domain = vino.domain || (m[1] || '').trim() || null;
    vino.nome_vino = vino.nome_vino || (m[2] || '').trim() || null;
    vino.anno = vino.anno || (m[3] || '').trim() || null;
  }
}

if (!vino.domain || !vino.nome_vino) {
  throw new Error('Dati vino incompleti: domain o nome_vino mancanti');
}

const anno = vino.anno ? `_${vino.anno}` : '';
const litri = vino.litraggio ? `_${vino.litraggio}` : '';

// 4. Recupera l'ID della cartella (preferisce sottocartella PRODOTTO)
let folderId = vino.productFolderId || vino.outputFolderId;

// Fallback finale: usa gli ID creati a inizio workflow
if (!folderId) {
  try {
    folderId = $('Store Product Folder ID').first().json.productFolderId || $('Store Folder ID').first().json.outputFolderId;
  } catch (e) {}
}

if (!folderId) {
  throw new Error('ID cartella di output non trovato');
}

return {
  nome_file: `${vino.domain}_${vino.nome_vino}${anno}${litri}.md`,
  contenuto_md: cleanHTML,
  folder_id: folderId
};

// Combina l'output di AI Agent con i dati del vino
// Obiettivo: mantenere SEMPRE i campi critici per Pulizia+Formattazione Testo (domain, nome_vino, folderId)
const aiOutput = $input.item.json || {};

function hasRequiredVinoFields(v) {
  return !!(v && v.domain && v.nome_vino);
}

let vino = null;

// 1) Se AI Agent ha già un vino completo, usa quello
if (hasRequiredVinoFields(aiOutput.vino)) {
  vino = aiOutput.vino;
}

// 2) Preferisci il paired item di Combine Data (più affidabile dell'accesso per index)
if (!vino) {
  const combinePaired = $('Combine Data');
  if (combinePaired && combinePaired.item && combinePaired.item.json && combinePaired.item.json.vino) {
    vino = combinePaired.item.json.vino;
  }
}

// 3) Fallback: ricostruisci dai dati correnti del batch (Split In Batches)
if (!vino) {
  const batchNode = $('Split In Batches');
  const b = (batchNode && batchNode.item && batchNode.item.json) ? batchNode.item.json : null;
  if (b && b.domain) {
    vino = {
      domain: b.domain,
      nome_vino: b.nome_vino,
      anno: b.anno,
      litraggio: b.litraggio,
      outputFolderId: b.outputFolderId,
      productFolderId: b.productFolderId
    };
  }
}

if (!vino) {
  throw new Error('Dati vino non trovati nel flusso. Assicurati che Combine Data e Split In Batches passino correttamente i dati del vino.');
}

return {
  json: {
    ...aiOutput,
    vino
  }
};

// Estrae profilo cantina dalla risposta Perplexity e lo associa al domain
// Nota: quando fullResponse=true, la risposta JSON è in $json.body

const prev = $('Prepare Perplexity Cantina Request').item.json;
const resolvedDomain = ((prev && prev.domain) ? prev.domain : '').trim();

if (!resolvedDomain) {
  throw new Error('Domain non trovato per la ricerca cantina');
}

const response = ($json && $json.body) ? $json.body : $json;
const content = (response && response.choices && response.choices[0] && response.choices[0].message && response.choices[0].message.content)
  ? response.choices[0].message.content
  : null;

if (!content) {
  throw new Error('Risposta Perplexity non valida per la ricerca cantina');
}

return { json: { domain: resolvedDomain, cantina_research: content } };

// Filtra i domain escludendo quelli che hanno già il file DOMINIO.md
// I dati arrivano dal Merge: items da Extract Cantina Research e item da Get Existing Domain Files
const allItems = $input.all();

let allDomains = [];
let existingFilesResponse = null;

for (const item of allItems) {
  if (item.json.files && Array.isArray(item.json.files)) {
    existingFilesResponse = item.json;
  } else if (item.json.domain) {
    allDomains.push(item);
  }
}

if (allDomains.length === 0) {
  throw new Error('Nessun domain trovato nel merge (domain)');
}

let existingFileNames = [];
let existingFilesArray = [];
if (existingFilesResponse && existingFilesResponse.files && Array.isArray(existingFilesResponse.files)) {
  existingFilesArray = existingFilesResponse.files;
  existingFileNames = existingFilesArray.map(f => (f.name || '').toLowerCase().trim()).filter(Boolean);
}

const domainFolderId = $('Store Domain Folder ID').first().json.domainFolderId;
if (!domainFolderId) {
  throw new Error('domainFolderId non trovato');
}

function expectedDomainFileName(domain) {
  const d = (domain || '').trim();
  if (!d) return null;
  return (d + '.md').toLowerCase().trim();
}

const domainsDaProcessare = allDomains.filter(item => {
  const expected = expectedDomainFileName(item.json.domain);
  if (!expected) return true;
  return !existingFileNames.includes(expected);
}).map(item => ({
  json: {
    domain: item.json.domain,
    cantina_research: item.json.cantina_research,
    domainFolderId
  }
}));

// FIX: Se non ci sono domain da processare, restituisci un item con flag isEmpty
// In questo modo il flusso continua e Check Empty Array (Domain) può decidere correttamente
if (domainsDaProcessare.length === 0) {
  console.log('Tutti i domain hanno già le descrizioni generate. Nessun file da processare.');
  return [{ json: { 
    isEmpty: true, 
    existingDomainFiles: existingFilesArray.map(f => f.name).filter(Boolean),
    existingDomainFilesCount: existingFilesArray.length
  } }];
}

return domainsDaProcessare;

// Assicura che domain e domainFolderId restino nel flusso dopo AI Agent (Domain)
const aiOutput = $input.item.json;
const domainItem = $('Split In Batches (Domain)').item.json;

const domain = aiOutput.domain || domainItem.domain;
const domainFolderId = aiOutput.domainFolderId || domainItem.domainFolderId;
const cantina_research = aiOutput.cantina_research || domainItem.cantina_research;

if (!domain || !domainFolderId) {
  throw new Error('Dati domain incompleti dopo AI Agent (Domain)');
}

return {
  json: {
    ...aiOutput,
    domain,
    domainFolderId,
    cantina_research
  }
};

// Pulizia + formattazione output domain -> DOMINIO.md
let rawHTML = null;
const output = $input.item.json.output;

if (typeof output === 'string') {
  rawHTML = output;
} else if (output && Array.isArray(output) && output[0] && output[0].content && Array.isArray(output[0].content) && output[0].content[0]) {
  rawHTML = output[0].content[0].text;
} else if (output && output.text) {
  rawHTML = output.text;
} else {
  throw new Error('Risposta del modello non valida (domain)');
}

if (!rawHTML || typeof rawHTML !== 'string') {
  throw new Error('Contenuto HTML non valido o vuoto (domain)');
}

let cleanHTML = rawHTML
  .replace(/<!DOCTYPE html>|<\/?html.*?>|<\/?head>|<\/?body>|<meta.*?>|<title>.*?<\/title>/gi, '')
  .trim();

const domain = ($input.item.json.domain || '').trim();
const folderId = $input.item.json.domainFolderId;

if (!domain) {
  throw new Error('Domain mancante per nome file (domain)');
}
if (!folderId) {
  throw new Error('domainFolderId mancante (domain)');
}

return {
  nome_file: `${domain}.md`,
  contenuto_md: cleanHTML,
  folder_id: folderId
};

// Messaggio finale domain: lista file DOMINIO.md creati
try {
  const filterNode = $('Filter Existing Domain Files');
  const allDomains = (filterNode && filterNode.all && filterNode.all().length > 0)
    ? filterNode.all().map(i => i.json)
    : [];

  const totalFiles = allDomains.length;
  if (totalFiles === 0) throw new Error('Nessun domain processato');

  const fileNames = allDomains.map(d => (d.domain || 'Domain-sconosciuto') + '.md').join('\n- ');

  // Recupera anche i file domain esistenti per il resoconto completo
  let existingDomainFiles = [];
  try {
    const getExistingDomainFilesNode = $('Get Existing Domain Files');
    if (getExistingDomainFilesNode && getExistingDomainFilesNode.first()) {
      const response = getExistingDomainFilesNode.first().json;
      if (response && response.files && Array.isArray(response.files)) {
        existingDomainFiles = response.files.map(f => f.name).filter(Boolean);
      }
    }
  } catch (e) {}

  return {
    json: {
      domainTotalFiles: totalFiles,
      domainFileNames: fileNames,
      existingDomainFilesCount: existingDomainFiles.length,
      existingDomainFileNames: existingDomainFiles.join('\n- ')
    }
  };
} catch (e) {
  return {
    json: {
      domainTotalFiles: 0,
      domainFileNames: '',
      existingDomainFilesCount: 0,
      existingDomainFileNames: ''
    }
  };
}

// Caso: nessun nuovo file domain da creare
// I file esistenti sono passati direttamente da Filter Existing Domain Files
let existingDomainFiles = [];
const inputData = $json || {};

// Prima prova a usare i dati passati direttamente
if (inputData.existingDomainFiles && Array.isArray(inputData.existingDomainFiles)) {
  existingDomainFiles = inputData.existingDomainFiles;
} else {
  // Fallback: recupera da Get Existing Domain Files
  try {
    const getExistingDomainFilesNode = $('Get Existing Domain Files');
    if (getExistingDomainFilesNode && getExistingDomainFilesNode.first()) {
      const response = getExistingDomainFilesNode.first().json;
      if (response && response.files && Array.isArray(response.files)) {
        existingDomainFiles = response.files.map(f => f.name).filter(Boolean);
      }
    }
  } catch (e) {
    console.log('Impossibile recuperare file domain esistenti: ' + e.message);
  }
}

const existingDomainFilesCount = existingDomainFiles.length;
const existingDomainFileNames = existingDomainFiles.join('\n- ');

return {
  json: {
    domainTotalFiles: 0,
    domainFileNames: '',
    existingDomainFilesCount: existingDomainFilesCount,
    existingDomainFileNames: existingDomainFileNames
  }
};

// Normalizza output prodotto (sia da Prepare Final Message che da Prepare Empty Message)
const j = $json || {};

return {
  json: {
    runId: '1',
    productTotalFiles: Number(j.totalFiles || 0),
    productFileNames: (j.fileNames || '').toString(),
    existingProductFilesCount: Number(j.existingFilesCount || 0),
    existingProductFileNames: (j.existingFileNames || '').toString(),
    outputFolderName: (j.outputFolderName || $('Workflow Configuration').first().json.outputFolderName || '').toString()
  }
};

// Normalizza output domain (sia da Prepare Final Message (Domain) che da Prepare Empty Message (Domain))
const j = $json || {};
return {
  json: {
    runId: '1',
    domainTotalFiles: Number(j.domainTotalFiles || 0),
    domainFileNames: (j.domainFileNames || '').toString(),
    existingDomainFilesCount: Number(j.existingDomainFilesCount || 0),
    existingDomainFileNames: (j.existingDomainFileNames || '').toString()
  }
};

// Compone messaggio Telegram quando prodotto+domain sono conclusi
const outputFolderName = ($json.outputFolderName || $('Workflow Configuration').first().json.outputFolderName || '').toString();
const pTotal = Number($json.productTotalFiles || 0);
const dTotal = Number($json.domainTotalFiles || 0);
const pFiles = ($json.productFileNames || '').toString().trim();
const dFiles = ($json.domainFileNames || '').toString().trim();

// File esistenti (già presenti nelle cartelle)
const existingPTotal = Number($json.existingProductFilesCount || 0);
const existingDTotal = Number($json.existingDomainFilesCount || 0);
const existingPFiles = ($json.existingProductFileNames || '').toString().trim();
const existingDFiles = ($json.existingDomainFileNames || '').toString().trim();

let msg = '🚀 **Workflow completato**\n\n';
msg += '📁 Cartella: ' + outputFolderName + '\n\n';

// Sezione Prodotti
msg += '✅ **Prodotti**:\n';
if (pTotal > 0 && pFiles) {
  msg += '📄 Nuovi file creati (' + pTotal + '):\n- ' + pFiles + '\n';
} else {
  msg += '📄 Nuovi file creati: 0\n';
}
if (existingPTotal > 0 && existingPFiles) {
  msg += '📂 File già presenti (' + existingPTotal + '):\n- ' + existingPFiles + '\n';
}
msg += '\n';

// Sezione Domain
msg += '✅ **Domain (produttori)**:\n';
if (dTotal > 0 && dFiles) {
  msg += '📄 Nuovi file creati (' + dTotal + '):\n- ' + dFiles + '\n';
} else {
  msg += '📄 Nuovi file creati: 0\n';
}
if (existingDTotal > 0 && existingDFiles) {
  msg += '📂 File già presenti (' + existingDTotal + '):\n- ' + existingDFiles;
}

return { json: { message: msg } };
